package com.madar.files;
import android.content.Context;import org.json.*;import java.io.*;import java.util.*;
/** Resolves chat references to owned files before any cloud request. Keeps every rendered revision. */
final class AgentMotion {
 static JSONObject create(Context c,JSONObject r)throws Exception{
  String thread=MotionProject.text(r,"thread",80,false);if(!thread.matches("[a-zA-Z0-9_-]{1,80}"))throw new IOException("محادثة غير صالحة");String text=MotionProject.text(r,"prompt",6000,false),voice=r.optString("voice","silma");if(!Arrays.asList("silma","none","recording").contains(voice))throw new IOException("اختر الصوت المعتمد أو تسجيلك أو بدون صوت");
  JSONObject p=MotionProject.create(c),brief=new JSONObject().put("text",text);String old=r.optString("previous","");
  Set<String> copied=new LinkedHashSet<>();JSONObject referenceMap=new JSONObject();if(!old.isEmpty()){JSONObject previous=MotionProject.load(c,old);if(!thread.equals(previous.optString("agentThread")))throw new IOException("المشروع لا يخص هذه المحادثة");JSONArray shots=new JSONArray();JSONArray oldShots=previous.getJSONArray("scenes");for(int n=0;n<oldShots.length();n++){JSONObject shot=oldShots.getJSONObject(n);shots.put(new JSONObject().put("title",shot.getString("title")).put("narration",shot.getString("narration")).put("composition",shot.optJSONObject("composition")));}brief.put("previous",new JSONObject().put("title",previous.getString("title")).put("scenes",shots).put("direction",previous.optJSONObject("direction")));if(previous.has("creativeRequest")){referenceMap=previous.getJSONObject("creativeRequest").optJSONObject("referenceMap");if(referenceMap==null)referenceMap=new JSONObject();String original=previous.getJSONObject("creativeRequest").optString("text");String revised="الطلب السابق:\n"+original+"\nالتعديل الحالي (غيّر المطلوب فقط):\n"+text;brief.put("text",revised.length()>6000?revised.substring(revised.length()-6000):revised);}for(String name:MotionCreative.assets(previous)){File target=MotionProject.asset(c,p.getString("id"),name);try(InputStream in=new FileInputStream(MotionProject.asset(c,old,name));OutputStream out=new FileOutputStream(target)){FilesUtil.copy(in,out);}copied.add(name);}}
  JSONArray input=r.optJSONArray("attachments");if(input==null)input=new JSONArray();if(input.length()>12)throw new IOException("الحد 12 مرفقًا في الطلب");File audio=null;Set<String> seen=new HashSet<>();for(int i=0;i<input.length();i++){String id=input.getString(i);if(!seen.add(id))continue;JSONObject info=AssistantFiles.info(c,id);File source=AssistantFiles.resolve(c,id);if(info.optString("kind").equals("image")){if(referenceMap.has(id)&&copied.contains(referenceMap.getString(id)))continue;if(copied.size()>=8)throw new IOException("اختر حتى ثماني صور مرجعية");String name=MotionImages.store(c,p.getString("id"),source);copied.add(name);referenceMap.put(id,name);}else if(info.optString("kind").equals("audio"))audio=source;}
  if(voice.equals("recording")){if(audio==null)throw new IOException("أرفق تسجيل التعليق من زر +، أو اختر الصوت الرجالي المعتمد");if(audio.length()>32L*1024*1024)throw new IOException("التسجيل كبير جدًا");try(InputStream in=new FileInputStream(audio);OutputStream out=new FileOutputStream(MotionProject.asset(c,p.getString("id"),"recording.media"))){FilesUtil.copy(in,out);}}
  brief.put("images",new JSONArray(copied)).put("referenceMap",referenceMap);if(text.contains("مدار"))brief.put("appFacts","مدار: أدوات ملفات وصور وفيديو وصوت وPDF. ينفذ أوامر الملفات المدعومة داخل المحادثة، ويسأل عن المدخلات الناقصة ويعيد الملفات الناتجة فيها. تحويل الصيغ وضغط الملفات، استخراج النص، تحويل PDF إلى Word ودمج PDF وصور إلى PDF، تحرير الفيديو وفصل الموسيقى مع خيارات محلية وColab. لا تدّع دعم ميزة لم تذكر في الطلب أو تظهر في الصور. الخدمات السحابية تحتاج اتصالًا وقد تتطلب تسجيل الدخول؛ ليست كل العمليات محلية أو بلا حدود.");p.put("creativeRequest",brief).put("agentThread",thread).put("agentTask",r.optString("task","")).put("voiceMode",voice).put("captions",false);MotionProject.save(c,p);return p;
 }
}
